fn inl_sqrtf_store<'a>(ctx: &'a Ctx, x: f64, y: Val<'a, F32>) -> f64 {
    let mut x = x;
    let mut y = y;
    if x > 0.0 {
        let mut guess: f64 = fp::frsqrte(x);
        guess = fp::fmul(
            fp::fmul(0.5, guess),
            (fp::fnmsub(fp::fmul(guess, guess), x, 3.0)),
        );
        guess = fp::fmul(
            fp::fmul(0.5, guess),
            (fp::fnmsub(fp::fmul(guess, guess), x, 3.0)),
        );
        guess = fp::fmul(
            fp::fmul(0.5, guess),
            (fp::fnmsub(fp::fmul(guess, guess), x, 3.0)),
        );
        (y).set(fp::frsp((fp::fmul(x, guess))));
        return (y).get();
    }
    return x;
}

